package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	var input []string
	for scanner.Scan() {
		input = append(input, scanner.Text())
	}
	if len(input) == 0 {
		return
	}

	parts := strings.Fields(input[0])
	if len(parts) < 2 {
		return
	}

	n, _ := strconv.Atoi(parts[0])
	m, _ := strconv.Atoi(parts[1])

	if n >= m {
		fmt.Println(n - m)
		return
	}

	current := map[int]struct{}{n: {}}
	steps := 0
	maxVal := m + m/2

	for {
		next := make(map[int]struct{})
		for x := range current {
			if x-1 >= 1 {
				nx := x - 1
				if nx == m {
					fmt.Println(steps + 1)
					return
				}
				next[nx] = struct{}{}
			}
			if x*2 <= maxVal {
				nx := x * 2
				if nx == m {
					fmt.Println(steps + 1)
					return
				}
				next[nx] = struct{}{}
			}
		}
		current = next
		steps++
	}
}

